procedure Inspect_Constant_Example is
   Data : aliased constant OpenCV.Core.UInt8_Mat_View.Buffer_Array :=
     (11 => 1, 12 => 2, 13 => 3, 14 => 4, 15 => 5, 16 => 6);

   procedure Inspect (Image : OpenCV.Core.Mat) is
